function section(s,id,localHref){return '<section id="'+id+'"><h2>'+esc(s.heading)+'</h2>'+s.body.map(b=>'<p>'+esc(b)+'</p>').join('')+(s.items?'<ul>'+s.items.map(x=>'<li>'+esc(x)+'</li>').join('')+'</ul>':'')+(s.table?'<div class="table-wrap" tabindex="0" role="region" aria-label="'+esc(s.table.caption)+'"><table><caption>'+esc(s.table.caption)+'</caption><thead><tr>'+s.table.headers.map(x=>'<th scope="col">'+esc(x)+'</th>').join('')+'</tr></thead><tbody>'+s.table.rows.map(row=>'<tr>'+row.map(x=>'<td>'+esc(x)+'</td>').join('')+'</tr>').join('')+'</tbody></table></div>':'')+(s.links?'<div class="text-links">'+s.links.map(x=>'<a href="'+localHref(x.href)+'">'+esc(x.label)+' →</a>').join('')+'</div>':'')+'</section>';}

function rateCheck(c){return '<section class="original-tool" id="cohort-rate-check"><h2>'+esc(c.heading)+'</h2><p>'+esc(c.intro)+'</p><div data-buyer-rate-check role="group" aria-label="'+esc(c.heading)+'" aria-describedby="cohort-rate-privacy"><div class="rate-grid">'+c.fields.map((label,i)=>'<label for="rate-count-'+i+'">'+esc(label)+'<input id="rate-count-'+i+'" data-rate-value type="text" inputmode="numeric" maxlength="16" autocomplete="off"></label>').join('')+'</div><label class="cohort-confirm"><input type="checkbox" data-rate-cohort>'+esc(c.cohort)+'</label><div class="rate-actions">'+[['calculate',c.calculate],['example',c.example],['clear',c.clear]].map(([key,label],i)=>'<button disabled type="button" class="button'+(i?' secondary':'')+'" data-rate-'+key+'>'+esc(label)+'</button>').join('')+'</div><dl>'+c.outputs.map(label=>'<dt>'+esc(label)+'</dt><dd data-rate-output>'+esc(c.unavailable)+'</dd>').join('')+'</dl><p data-rate-status role="status" aria-live="polite">'+esc(c.empty)+'</p><p id="cohort-rate-privacy">'+esc(c.privacy)+'</p><script type="application/json" data-rate-config>'+JSON.stringify(c).replace(/</g,'\u003c')+'</script></div></section>';}

