 const faqs='<section class="faqs" id="frequently-asked-questions"><h2>'+esc(c.faq)+'</h2><div class="faq-list">'+p.faqs.map(f=>'<details><summary>'+esc(f.question)+'</summary><p>'+esc(f.answer)+'</p></details>').join('')+'</div></section>';
 const sources='<section class="sources" id="sources"><h2>'+esc(c.sources)+'</h2><p>'+esc(p.sourceMethodology)+' '+esc(c.checked)+'</p><ol>'+p.sources.map(s=>'<li><a href="'+esc(localHref(s.href))+'">'+esc(s.label)+'</a></li>').join('')+'</ol></section>';
 const article=p.sections.map((s,i)=>section(s,'guide-section-'+(i+1),localHref)+(i===0?tool:'')+(p.rateCheck&&i===5?rateCheck(p.rateCheck):'')+(i===1?ctas[0]:i===3?ctas[1]:'')).join('')+decision+faqs+sources;
 html=html.replace(/<article>[\s\S]*?<\/article>/,'<article>'+article+'</article>');
 const toc=p.sections.map((s,i)=>'<a href="#guide-section-'+(i+1)+'">'+esc(s.heading)+'</a>'+(i===0?'<a href="#buyer-worksheet">'+esc(p.tool.navLabel)+'</a>':'')+(p.rateCheck&&i===5?'<a href="#cohort-rate-check">'+esc(p.rateCheck.navLabel)+'</a>':'')).join('')+'<a href="#buyer-decision-guide">'+esc(p.decisionGuide.heading)+'</a><a href="#frequently-asked-questions">'+esc(c.faq)+'</a><a href="#sources">'+esc(c.sources)+'</a>';
 html=html.replace(/<details class="mobile-toc">[\s\S]*?<\/details>/,'<details class="mobile-toc"><summary><span><small>'+esc(c.toc)+'</small><strong class="current-section">'+esc(p.sections[0].heading)+'</strong></span><span class="toc-action">'+esc(c.sections)+'</span></summary><nav aria-label="'+esc(c.nav)+'">'+toc+'</nav></details>');
 html=html.replace(/<aside class="toc">[\s\S]*?<\/aside>/,'<aside class="toc"><div class="toc-label"><span>'+esc(c.article)+'</span><strong>'+esc(c.toc)+'</strong></div>'+toc+'<div class="toc-progress"><span></span></div></aside>');
 html=html.replace(/<h1>[\s\S]*?<\/h1>/,'<h1>'+esc(p.h1)+'</h1>').replace(/<p class="answer">[\s\S]*?<\/p>/,'<p class="answer">'+esc(p.answer)+'</p>');
 const revision={en:'October 28, 2026',es:'28 de octubre de 2026',ca:'28 d’octubre de 2026',fr:'28 octobre 2026'}[l];
 html=html.replace(/(<p class="meta">[\s\S]*? · [^<]*?)(?:October 27, 2026|27 de octubre de 2026|27 d’octubre de 2026|27 octobre 2026)(<\/p>)/,(m,a,z)=>a+revision+z);
 if(l!=='en')html=html.replace(/(<p class="meta">[\s\S]*? · )Updated /,(m,a)=>a+({es:'Actualizado ',ca:'Actualitzat ',fr:'Mis à jour '}[l]));
