 html=html.replace(/<title>[\s\S]*?<\/title>/,'<title>'+esc(p.title)+'</title>');
 for(const [type,name,value]of [['name','description',p.description],['property','og:title',p.title],['property','og:description',p.description],['name','twitter:title',p.title],['name','twitter:description',p.description]]){
  html=html.replace(new RegExp('(<meta '+type+'="'+name+'" content=")[^"]*(")'),(m,a,z)=>a+esc(value)+z);
 }
 html=html.replace(/(<script type="application\/ld\+json">)([\s\S]*?)(<\/script>)/,(m,a,json,z)=>{const data=JSON.parse(json);for(const n of data['@graph']){if(n['@type']==='Article'){n.name=p.h1;n.headline=p.h1;n.description=p.description;n.inLanguage=l;n.datePublished='2026-10-28T14:00:00+01:00';n.dateModified='2026-10-28T14:00:00+01:00';}if(n['@type']==='FAQPage')n.mainEntity=p.faqs.map(f=>({'@type':'Question',name:f.question,acceptedAnswer:{'@type':'Answer',text:f.answer}}));}return a+JSON.stringify(data).replace(/</g,'\\u003c')+z;});
 html=html.replace('</head>','<link rel="stylesheet" href="'+assetUrl('/buyer-guide-worksheet.css')+'"><script src="'+assetUrl('/buyer-guide-worksheet.js')+'" defer></script></head>');
 if(p.rateCheck)html=html.replace('</head>','<link rel="stylesheet" href="'+assetUrl('/buyer-rate-check.css')+'"><script src="'+assetUrl('/buyer-rate-check.js')+'" defer></script></head>');
 fs.writeFileSync(file,html);
