for(const [l,items]of Object.entries(contextual)){const pre=l==='en'?'':'/'+l;for(const [route,n,links]of items){const f=path.join(root,(pre+route).slice(1),'index.html');let h=fs.readFileSync(f,'utf8');assert(!h.includes('class="buyer-growth-link"'));const p='<p class="buyer-growth-link">'+links.map(([u,t])=>'<a href="'+pre+u+'">'+esc(t)+'</a>').join(' · ')+'.</p>';const re=new RegExp('(<section id="guide-section-'+n+'">[\\s\\S]*?)(</section>)');assert(re.test(h),route+' contextual section missing');h=h.replace(re,(m,a,z)=>a+p+z);fs.writeFileSync(f,h);}}
let sitemap=fs.readFileSync(path.join(root,'sitemap.xml'),'utf8');for(const l of ['en','es','ca','fr']){const pre=l==='en'?'':'/'+l;for(const route of ['/resources/',...guides.map(g=>g.en.path)]){const url='https://outbound-lead-generation.com'+pre+route;sitemap=sitemap.replace(/<url><loc>([^<]+)<\/loc><lastmod>([^<]+)<\/lastmod><\/url>/g,(m,u)=>u===url?'<url><loc>'+u+'</loc><lastmod>2026-10-28</lastmod></url>':m);}}fs.writeFileSync(path.join(root,'sitemap.xml'),sitemap);
